      "✓ 已打开界面对比，并把「AI 协助分析」提示词填入当前会话。请核对后发送；写回后结论会出现在下方差异区。": '✓ UI compare opened and "AI assist analysis" prompt filled. Review and send; conclusions appear in the diff area after publish.',
      "✓ 已将「AI 推荐文件」提示词填入当前会话。请核对后发送；模型调用 tracescope_publish_page_rematch 后，侧栏会自动选中推荐文件。可继续对话纠正并再次写回。": '✓ "AI suggested files" prompt filled. After tracescope_publish_page_rematch, the sidebar selects the top file. Continue in chat to correct and publish again.',
      "✓ 已写回 AI 文件推荐并选中 Top1": "✓ AI file suggestions published; Top1 selected",
      "1. 以设计稿为唯一准绳，针对上述不一致逐项给出如何改代码贴近设计稿的具体做法（尺寸 / 位置 / 间距 / 颜色 / 字号等）。": "1. Treat the design as source of truth. For each mismatch, give concrete code changes (size / position / spacing / color / font size, etc.).",
      "2. 对列表、分页、WebView 等运行时动态区域，在差异项中标明不确定性，并给出设计稿期望内容（不必做可视化还原）。": "2. For dynamic areas (lists, pagination, WebView), mark uncertainty in diffs and state expected design content (no visual replay needed).",
      "3. 区分哪些是可直接修正的实现问题，哪些受运行时数据或字体回退影响、需要我确认；有疑问随时问我，我们连续完善。": "3. Separate fixable implementation issues from runtime/data/font-fallback cases that need my confirmation; ask anytime.",
